using System.Data;using MediDesk.Business.Interfaces;using MediDesk.Common.Contracts.Administration;using MediDesk.Common.Contracts.Catalog;using Microsoft.Data.SqlClient;namespace MediDesk.Data.Repositories;public sealed class UserAdminRepository(SqlConnectionFactory f):IUserAdminRepository{public async Task<PagedResponse<UserAdminDto>>GetPageAsync(UserAdminQuery q,CancellationToken ct){await using var c=f.Create();await c.OpenAsync(ct);await using var cmd=new SqlCommand("SELECT COUNT(1) FROM Users u WHERE (@S IS NULL OR u.FullName LIKE @L OR u.Email LIKE @L);SELECT u.Id,u.FullName,u.Email,r.Name,u.IsActive,NULL,u.RowVersion FROM Users u JOIN Roles r ON r.Id=u.RoleId WHERE (@S IS NULL OR u.FullName LIKE @L OR u.Email LIKE @L) ORDER BY u.FullName OFFSET @O ROWS FETCH NEXT @P ROWS ONLY",c);cmd.Parameters.Add("@S",SqlDbType.NVarChar,160).Value=(object?)q.Search??DBNull.Value;cmd.Parameters.Add("@L",SqlDbType.NVarChar,170).Value=q.Search is null?DBNull.Value:$"%{q.Search}%";cmd.Parameters.Add("@O",SqlDbType.Int).Value=(q.Page-1)*q.PageSize;cmd.Parameters.Add("@P",SqlDbType.Int).Value=q.PageSize;await using var r=await cmd.ExecuteReaderAsync(ct);await r.ReadAsync(ct);var total=r.GetInt32(0);await r.NextResultAsync(ct);var a=new List<UserAdminDto>();while(await r.ReadAsync(ct))a.Add(new(r.GetInt64(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetBoolean(4),null,Convert.ToBase64String((byte[])r[6])));return new(a,q.Page,q.PageSize,total);}public async Task<bool>UpdateAsync(long id,UpdateUserAdminRequest x,long u,CancellationToken ct){await using var c=f.Create();await c.OpenAsync(ct);await using var cmd=new SqlCommand("UPDATE Users SET FullName=@N,RoleId=(SELECT Id FROM Roles WHERE Name=@R),IsActive=@A,UpdatedAtUtc=SYSUTCDATETIME() WHERE Id=@Id AND RowVersion=@V",c);cmd.Parameters.Add("@N",SqlDbType.NVarChar,160).Value=x.FullName;cmd.Parameters.Add("@R",SqlDbType.NVarChar,80).Value=x.Role;cmd.Parameters.Add("@A",SqlDbType.Bit).Value=x.IsActive;cmd.Parameters.Add("@Id",SqlDbType.BigInt).Value=id;cmd.Parameters.Add("@V",SqlDbType.Timestamp).Value=Convert.FromBase64String(x.RowVersion);return await cmd.ExecuteNonQueryAsync(ct)>0;}}

